using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;using OperationsRequests.Domain;namespace OperationsRequests.Data;public sealed class DemoSeeder(ApplicationDbContext db,UserManager<ApplicationUser> users,RoleManager<IdentityRole> roles,IConfiguration cfg){public async Task SeedAsync(){await db.Database.MigrateAsync();foreach(var r in Roles.All)if(!await roles.RoleExistsAsync(r))await roles.CreateAsync(new IdentityRole(r));if(!await db.Platforms.AnyAsync()){var p=new Platform{Name="Global Operations"};foreach(var country in new[]{("Indonesia","ID"),("Malaysia","MY")}){var c=new Country{Name=country.Item1,Code=country.Item2,Platform=p};for(var t=1;t<=2;t++){var tr=new Territory{Name=$"{country.Item1} Territory {t}",Country=c};for(var s=1;s<=2;s++)db.Add(new Site{Name=$"{country.Item1} Site {t}-{s}",Code=$"{country.Item2}-T{t}S{s}",Territory=tr});}}await db.SaveChangesAsync();}var password=cfg["Demo:Password"];if(string.IsNullOrWhiteSpace(password))return;var sites=await db.Sites.Include(x=>x.Territory).ThenInclude(x=>x.Country).ToListAsync();var specs=new List<(string,string,string,Site?)>{(Roles.PlatformAdmin,"admin@demo.local","Platform Admin",null)};foreach(var c in sites.Select(x=>x.Territory.Country).DistinctBy(x=>x.Id)){specs.Add((Roles.CountryOpsManager,$"country.{c.Code.ToLower()}@demo.local",$"{c.Name} Ops",sites.First(x=>x.Territory.CountryId==c.Id)));}foreach(var t in sites.Select(x=>x.Territory).DistinctBy(x=>x.Id)){specs.Add((Roles.TerritoryManager,$"territory.{t.Id}@demo.local",$"{t.Name} Manager",sites.First(x=>x.TerritoryId==t.Id)));}foreach(var s in sites){specs.Add((Roles.SiteManager,$"site.{s.Id}@demo.local",$"{s.Name} Manager",s));specs.Add((Roles.StaffMember,$"staff.{s.Id}@demo.local",$"{s.Name} Staff",s));}foreach(var x in specs)if(await users.FindByEmailAsync(x.Item2)is null){var u=new ApplicationUser{UserName=x.Item2,Email=x.Item2,EmailConfirmed=true,DisplayName=x.Item3,CountryId=x.Item4?.Territory.CountryId,TerritoryId=x.Item4?.TerritoryId,SiteId=x.Item4?.Id};var result=await users.CreateAsync(u,password);if(!result.Succeeded)throw new InvalidOperationException(string.Join(';',result.Errors.Select(e=>e.Description)));await users.AddToRoleAsync(u,x.Item1);db.AuditEvents.Add(new AuditEvent{Action="UserCreated",ActorId=u.Id,ActorName="Seeder",Note=x.Item1});}if(!await db.TrainingRequests.AnyAsync()){var staff=await users.Users.Where(x=>x.Email!.StartsWith("staff.")).ToListAsync();for(var i=0;i<16;i++){var u=staff[i%staff.Count];var r=new TrainingRequest{RequestNumber=$"REQ-DEMO-{i+1:000}",Title=$"Demo request {i+1}",Description="Seeded operational request.",SiteId=u.SiteId!.Value,RequestedById=u.Id,Type=(RequestType)(i%5),Priority=(RequestPriority)(i%3),Status=i%4==0?RequestStatus.UnderReview:RequestStatus.Submitted,CreatedAt=DateTimeOffset.UtcNow.AddDays(-i)};r.AuditEvents.Add(new AuditEvent{Action="Submitted",ActorId=u.Id,ActorName=u.DisplayName,NewStatus=r.Status});db.Add(r);}}await db.SaveChangesAsync();}}
